<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;class TrainingProgram extends Model{protected $fillable=['company_id','year','version','title','general_objective','specific_objectives','scope','starts_at','ends_at','status','prepared_by','prepared_at','reviewed_at','approved_at','approved_by','approval_justification','created_by','updated_by'];protected $casts=['starts_at'=>'date','ends_at'=>'date','prepared_at'=>'datetime','reviewed_at'=>'datetime','approved_at'=>'datetime'];public function company(){return$this->belongsTo(PerfilEmpresa::class,'company_id');}public function items(){return$this->hasMany(TrainingProgramItem::class);}public function reviews(){return$this->hasMany(TrainingProgramReview::class);}public function preparer(){return$this->belongsTo(Empleado::class,'prepared_by');}public function scopeForCompany($q,int$id){return$q->where('company_id',$id);}}
